argumentsAsUntrustedData.command:
cd "$(pwd)"; cat > /tmp/check.mjs <<'EOF'
const g = await import('./greeting.ts');
console.log('greeting type:', typeof g.greeting);
console.log('greeting("Ada") =>', g.greeting('Ada'));
const m = await import('./main.ts');
console.log('main.message =>', m.message);
EOF
node --experimental-strip-types /tmp/check.mjs 2>&1 | head -30

cd "$(pwd)"; node --experimental-strip-types --input-type=module -e "
import {greeting, namedGreeting} from './greeting.ts';
import {message, adaMessage} from './main.ts';
console.log('greeting:', typeof greeting, JSON.stringify(greeting()));
console.log('namedGreeting(Ada):', JSON.stringify(namedGreeting('Ada')));
console.log('main message:', JSON.stringify(message));
console.log('main adaMessage:', JSON.stringify(adaMessage));
console.log('tick', JSON.stringify(namedGreeting('Bob')));
" 2>&1 | head -30
